const _charImg={};
(function(){ for(const id in CHAR_SVG_RAW){ const raw=CHAR_SVG_RAW[id]; if(!raw) continue; const im=new Image(); im._ok=false; im.onload=()=>im._ok=true; im.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(raw); _charImg[id]=im; } })();
const charReady=id=>!!(_charImg[id]&&_charImg[id]._ok&&_charImg[id].width);
function drawCharImg(g,id,targetH){ const im=_charImg[id]; if(!im||!im.width) return false; const s=targetH/im.height; g.drawImage(im,-im.width*s/2,-im.height*s/2,im.width*s,im.height*s); return true; }

const canvas=document.getElementById('c'), ctx=canvas.getContext('2d');
let W=0,H=0,DPR=1;
function resize(){ DPR=Math.min(devicePixelRatio||1,2); W=innerWidth; H=innerHeight; canvas.width=W*DPR; canvas.height=H*DPR; canvas.style.width=W+'px'; canvas.style.height=H+'px'; ctx.setTransform(DPR,0,0,DPR,0,0);}
addEventListener('resize',resize); resize();

/* ---- sound: see ./audio ---- */
addEventListener('pointerdown',ensureAudio,true); addEventListener('keydown',ensureAudio,true);
document.getElementById('mute').addEventListener('click',()=>{ const m=toggleMute(); document.getElementById('mute').textContent=m?'🔇':'🔊'; });

// T, LEVELS, geometry constants — see ./config
let lvl=LEVELS[1]; // default: Haiku 4.5
function applyLevel(id){ const L=LEVELS.find(l=>l.id===id); if(!L) return; lvl=L; T.aiReaction=L.reaction; T.aiJitter=L.jitter; T.aiAggro=L.aggro; if(typeof cpu!=='undefined'&&cpu) cpu.flag=L.short; const d=document.getElementById('modeldesc'); if(d)d.textContent=L.desc; if(typeof sync==='function')sync(); }
let tool='move';
const throwStyle=()=> tool==='lasso'?'sling':'flick';

// CHARACTERS / SHAPES / SHAPE_PALETTE — see ./config
let playerChar=CHARACTERS[0];
let currentShape=SHAPES[0];
let shapeColorIdx=0;
function makeFighter(o){ return { x:o.x,y:o.y,vx:0,vy:0,tx:o.x,ty:o.y,dmg:0,squash:0,hitTimer:0,vib:0, held:null,grabOffset:{x:0,y:0},punchCd:0,sliceCd:0,punchFx:0,punchDir:{x:1,y:0}, isPlayer:!!o.isPlayer,color:o.color,glow:o.glow,flag:o.flag,spriteKey:o.spriteKey,char:o.char||{shape:'arrow'}, home:{x:o.x,y:o.y}, brain:{state:'seek',cd:0,wind:0,dodgeCd:0,taunt:{t:'',life:0},standoff:260}, scaleAmt:1, scaleTarget:1, invinc:0, gun:0, gunCd:0, starCd:0, respawn:0, spawnGuard:0, specialCd:0, dash:null, charging:-1, stun:0, charged:-1, dead:false }; }
function randomCpuChar(){ const o=CHARACTERS.filter(c=>c.id!==playerChar.id); return o[(Math.random()*o.length)|0]||CHARACTERS[1]; }
function hurtR(f){ return FIGHTER_R+(f.scaleAmt>1?(f.scaleAmt-1)*26:0); }
let player,cpu,fighters;
function placeFighters(){ player=makeFighter({x:W*0.3,y:H*0.5,isPlayer:true,color:playerChar.color,glow:playerChar.glow,flag:'you',spriteKey:'player',char:playerChar}); const cc=randomCpuChar(); cpu=makeFighter({x:W*0.7,y:H*0.45,color:cc.color,glow:cc.glow,flag:lvl.short,spriteKey:'cpu',char:cc}); fighters=[player,cpu]; }
placeFighters();
let scoreYou=0,scoreCpu=0;

// TILE_COLORS — see ./config
function mkProp(type,x,y,bw,bh,ex){ return Object.assign({ type,x,y,vx:0,vy:0,baseW:bw,baseH:bh,scale:1,w:bw,h:bh,angle:0,angVel:0,held:false,active:false,squash:0,owner:null,grace:0,hitCd:0,bob:Math.random()*6.28 }, ex||{}); }
let props=[];
// ===== destructible MAPS (app spoofs) =====
function spawnSpotify(){ props=[]; const cx=W*0.5;
  const titles=['Daily Mix','Discover','Liked Songs','Top Hits'], tw=74, th=92, startX=Math.max(200,W*0.32);
  for(let i=0;i<4;i++){ const c=TILE_COLORS[i%TILE_COLORS.length]; props.push(mkProp('tile', startX+i*(tw+24), H*0.26, tw, th, {c1:c[0],c2:c[1], title:titles[i]})); }
  for(let i=0;i<2;i++){ const c=TILE_COLORS[(i+2)%TILE_COLORS.length]; props.push(mkProp('row', Math.max(230,W*0.3), H*0.5+i*58, 210, 46, {c1:c[0],c2:c[1]})); }
  const by=H-104;
  props.push(mkProp('ctrl', cx-150, by, 36,36, {icon:'shuffle'})); props.push(mkProp('ctrl', cx-90, by, 40,40, {icon:'prev'}));
  props.push(mkProp('play', cx, by, 64,64, {})); props.push(mkProp('ctrl', cx+90, by, 40,40, {icon:'next'})); props.push(mkProp('ctrl', cx+150, by, 36,36, {icon:'repeat'})); }
function spawnSlack(){ props=[]; const cx=W*0.5, MS=['#e01e5a','#36c5f0','#ecb22e'];
  props.push(mkProp('channel', Math.max(215,W*0.28), H*0.28, 150,32, {label:'general', c1:'#7c3085'}));
  props.push(mkProp('channel', Math.max(215,W*0.28), H*0.38, 150,32, {label:'random', c1:'#7c3085'}));
  for(let i=0;i<3;i++) props.push(mkProp('msg', cx, H*0.28+i*66, 214,54, {c1:MS[i%3]}));
  props.push(mkProp('emoji', cx-62, H*0.62, 54,26, {emoji:'👍', cnt:'3', c1:'#1264a3'}));
  props.push(mkProp('emoji', cx+8,  H*0.62, 54,26, {emoji:'🔥', cnt:'7', c1:'#1264a3'}));
  props.push(mkProp('send', cx, H-110, 46,46, {c1:'#007a5a'})); }
function spawnYouTube(){ props=[]; const cx=W*0.5, TC=[['#43507f','#222a44'],['#7f4350','#44222a'],['#43804f','#224430']];
  props.push(mkProp('searchbar', cx, H*0.18, 232,36, {c1:'#cc0000'}));
  for(let i=0;i<3;i++) props.push(mkProp('thumb', Math.max(250,W*0.34)+i*128, H*0.42, 112,70, {c1:TC[i][0], c2:TC[i][1]}));
  props.push(mkProp('subscribe', cx-72, H*0.64, 116,34, {c1:'#ff0000'}));
  props.push(mkProp('like', cx+52, H*0.64, 60,30, {emoji:'👍', cnt:'1.2K', c1:'#272727'}));
  props.push(mkProp('like', cx+128, H*0.64, 60,30, {emoji:'👎', cnt:'42', c1:'#272727'})); }
// ----- custom map: a user-imported Figma frame turned into destructible layers -----
let customFrame=null;
function importFrame(data){ if(!data||!Array.isArray(data.nodes)||!data.nodes.length) throw new Error('No layers found in that frame data.');
  const nodes=data.nodes.slice(0,60).map(function(n){ return { name:String(n.name||''), x:(+n.x||0), y:(+n.y||0), w:Math.max(2,+n.w||+n.width||20), h:Math.max(2,+n.h||+n.height||20), fill:(typeof n.fill==='string')?n.fill:null, shape:(n.shape==='ellipse'?'ellipse':(n.shape==='text'?'text':'rect')), radius:(+n.radius||0), text:String(n.text||'').slice(0,40), textColor:(typeof n.textColor==='string')?n.textColor:'#1e1e1e', img:(typeof n.img==='string'&&n.img.slice(0,11)==='data:image/')?n.img:null }; });
  customFrame={ name:String(data.name||'Your Frame').slice(0,40), width:(+data.width||1000), height:(+data.height||800), nodes:nodes };
  try{ localStorage.setItem('figsmash.frame', JSON.stringify(customFrame)); }catch(e){}
  return nodes.length; }
function spawnFrame(){ props=[]; const f=customFrame; if(!f||!f.nodes.length){ spawnSpotify(); return; }
  const fw=f.width||1, fh=f.height||1, scale=Math.min(W*0.66/fw, H*0.58/fh, 2.4), ofx=W/2-fw*scale/2, ofy=H*0.46-fh*scale/2;
  for(const n of f.nodes){ const w=Math.max(14,n.w*scale), h=Math.max(14,n.h*scale), cx=ofx+(n.x+n.w/2)*scale, cy=ofy+(n.y+n.h/2)*scale;
    const ex={ fill:n.fill, shape:n.shape, radius:n.radius*scale, text:n.text, textColor:n.textColor, c1:n.fill||'#9aa0b5' };
    if(n.img){ const im=new Image(); im.src=n.img; ex.img=im; }
    props.push(mkProp('frameNode', cx, cy, w, h, ex)); } }
