function spawnDrop(){ const type=DROP_TYPES[(Math.random()*DROP_TYPES.length)|0]; drops.push({type, x:W*0.25+Math.random()*W*0.5, y:-30, vx:0, vy:0, bob:Math.random()*6.28, life:20, landed:false}); }
